<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {api,apiResult,errorText} from '@/lib/api'
import {dateTime} from '@/lib/format'
import {aiList,clone,enc,type AIRecord} from '@/features/ai/helpers'
const providers=ref<AIRecord[]>([]),status=ref<AIRecord>(),error=ref(''),loading=ref(false),busy=ref(false),drawer=ref(false),tab=ref('connection'),editing=ref<AIRecord>(),form=reactive<AIRecord>({}),secret=ref(''),check=ref<AIRecord>()
const defaults={name:'',kind:'OPENAI_COMPATIBLE',mode:'CLOUD',baseUrl:'',model:'',enabled:false,allowExternal:false,allowInsecureLocal:false,vision:false,schemaMode:'JSON_OBJECT',timeoutSeconds:120,maxOutputTokens:4096,dailyRequestLimit:50,tokenParameter:'max_tokens'}
const activeCount=computed(()=>providers.value.filter(p=>p.enabled).length)
async function load(){loading.value=true;error.value='';try{[providers.value,status.value]=await Promise.all([aiList('/api/v1/ai/providers'),api('/api/v1/ai/status')])}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function edit(p?:AIRecord){editing.value=p;Object.assign(form,clone(defaults));if(p)for(const key of Object.keys(defaults))if(p[key]!==undefined)form[key]=p[key];secret.value='';check.value=undefined;tab.value='connection';drawer.value=true;error.value=''}
async function save(){busy.value=true;error.value='';try{const body:AIRecord={};for(const key of Object.keys(defaults))body[key]=form[key];if(!body.name.trim()||!body.model.trim())throw new Error('请输入服务名称和模型标识');const url=new URL(body.baseUrl);if(url.username||url.password||url.hash||url.search)throw new Error('服务地址不能包含凭据、参数或片段');if(secret.value.trim())body.apiKey=secret.value.trim();const result=await apiResult(editing.value?'/api/v1/ai/providers/'+enc(editing.value.providerId):'/api/v1/ai/providers',editing.value?'PATCH':'POST',body,editing.value?{etag:'"'+editing.value.revision+'"'}:{});secret.value='';editing.value=result.data;drawer.value=false;await load();ElMessage.success('模型服务已保存；连接测试通过后再用于资料任务')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function runCheck(p:AIRecord){busy.value=true;error.value='';check.value=undefined;try{check.value={...(await api('/api/v1/ai/providers/'+enc(p.providerId)+'/checks','POST',{})),providerName:p.name};await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(load);onBeforeUnmount(()=>{secret.value=''})
</script>
<template><div>
<div class="page-heading"><div><h1>模型服务设置</h1><p>连接客户选择的兼容 API 或内网模型，凭据仅保存在服务器。</p></div><div class="toolbar"><el-button @click="load" :loading="loading">刷新</el-button><el-button type="primary" @click="edit()">添加模型服务</el-button></div></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<div class="stats-grid"><div class="stat-card"><span>当前 AI 状态</span><strong>{{activeCount?'可选择服务':'未启用'}}</strong><small>关闭模型不影响既有数据采集和转发</small></div><div class="stat-card"><span>启用的服务</span><strong>{{activeCount}} <em>/ {{providers.length}}</em></strong><small>每次资料导入可选择处理位置</small></div><div class="stat-card"><span>今日模型请求</span><strong>{{status?.todayRequests??'—'}}</strong><small>以服务器实际调用记录为准</small></div><div class="stat-card"><span>本机 PDF 提取</span><strong class="small-stat">{{status?.extraction?.pdfTextAvailable?'文字提取可用':'需配置工具'}}</strong><small>扫描页需要视觉能力或补充文字资料</small></div></div>
<section class="panel"><h2 class="section-title">模型服务</h2><el-table :data="providers" v-loading="loading" empty-text="尚未配置服务，可稍后填写兼容 API 地址和密钥"><el-table-column prop="name" label="服务" min-width="160"/><el-table-column label="接口 / 模型" min-width="220"><template #default="{row}">{{row.kind}}<div class="mono muted">{{row.model}}</div></template></el-table-column><el-table-column label="处理位置" width="110"><template #default="{row}">{{row.mode==='CLOUD'?'云端':'客户内网'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'已启用':'已关闭'}}</el-tag></template></el-table-column><el-table-column label="认证" width="100"><template #default="{row}">{{row.hasCredential?'已配置':'未配置'}}</template></el-table-column><el-table-column label="能力" min-width="140"><template #default="{row}">{{row.vision?'文字与图像':'文字'}}<div class="muted">{{row.schemaMode}}</div></template></el-table-column><el-table-column label="操作" min-width="170"><template #default="{row}"><el-button link type="primary" @click="edit(row)">设置</el-button><el-button link :loading="busy" @click="runCheck(row)">测试连接</el-button></template></el-table-column></el-table><p class="muted">连接测试只发送最小测试内容，不发送业务文档；云端测试可能产生少量 API 用量。测试通过不代表设备协议已经验证。</p></section>
<section v-if="check" class="panel"><h2 class="section-title">最近连接测试 · {{check.providerName}}</h2><el-alert :type="check.passed?'success':'warning'" :title="check.message||(check.passed?'最小请求与返回结构通过':'服务未通过测试')" :closable="false"/><p class="muted">{{dateTime(check.checkedAt)}} · 实际用量 {{JSON.stringify(check.usage||{})}}</p></section>
<section class="panel"><h2 class="section-title">默认运行方式</h2><p>没有模型时仍可上传资料、编辑协议草稿和使用已发布模板。启用云端服务后，仅在用户选择该服务并提交资料任务时发送资料。已发布解析规则运行时不调用模型。</p><p class="muted">不同兼容服务支持的图像与结构化输出可能不同。请按服务的实际能力配置；内网 HTTP 需要明确开启，跨主机服务应由客户网络或认证代理保护。</p></section>
<el-drawer v-model="drawer" :title="editing?'编辑模型服务':'添加模型服务'" size="min(760px, 97vw)" :close-on-click-modal="!busy" :show-close="!busy" @closed="secret=''">
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top" :disabled="busy"><el-tabs v-model="tab">
<el-tab-pane label="服务连接" name="connection"><div class="form-grid"><el-form-item label="服务名称" required><el-input v-model="form.name" maxlength="100" placeholder="例如 客户内网模型"/></el-form-item><el-form-item label="接口类型"><el-select v-model="form.kind"><el-option label="OpenAI 兼容接口" value="OPENAI_COMPATIBLE"/><el-option label="Ollama 原生接口" value="OLLAMA"/></el-select></el-form-item><el-form-item label="处理位置"><el-select v-model="form.mode"><el-option label="云端服务" value="CLOUD"/><el-option label="客户内网" value="LOCAL"/></el-select></el-form-item><el-form-item label="模型标识" required><el-input v-model="form.model" maxlength="128" placeholder="服务提供商的模型 ID"/></el-form-item></div><el-form-item label="API 基础地址" required><el-input v-model="form.baseUrl" placeholder="兼容接口填写含 /v1 的基础地址；Ollama 填服务根地址"/><span class="muted">不要填写聊天页面地址，也不要在 URL 中填写密钥。</span></el-form-item><el-form-item :label="editing?.hasCredential?'替换 API 密钥（留空保留）':'API 密钥（内网无认证时可空）'"><el-input v-model="secret" type="password" show-password autocomplete="new-password" placeholder="只提交到本平台服务器，不保存到浏览器"/></el-form-item><el-form-item label="启用此服务"><el-switch v-model="form.enabled"/></el-form-item></el-tab-pane>
<el-tab-pane label="隐私与范围" name="privacy"><el-form-item label="允许向云端发送资料"><el-switch v-model="form.allowExternal" :disabled="form.mode!=='CLOUD'"/><p class="muted">云端启用必须明确允许外部发送。上传资料本身先保存到本机，只有模型任务才发送选定资料。</p></el-form-item><el-form-item label="允许内网明文 HTTP"><el-switch v-model="form.allowInsecureLocal" :disabled="form.mode!=='LOCAL'"/><p class="muted">仅用于受控的本机或内网服务；生产优先使用 HTTPS。</p></el-form-item><el-form-item label="服务支持图像输入"><el-switch v-model="form.vision"/><p class="muted">扫描件与图片需要此能力；不要只因为接口兼容就开启。</p></el-form-item><el-form-item label="结构化输出方式"><el-select v-model="form.schemaMode"><el-option label="JSON Object（本平台追加校验）" value="JSON_OBJECT"/><el-option label="JSON Schema（服务须支持）" value="JSON_SCHEMA"/></el-select></el-form-item></el-tab-pane>
<el-tab-pane label="配额与运行" name="limits"><div class="form-grid"><el-form-item label="请求超时 秒"><el-input-number v-model="form.timeoutSeconds" :min="10" :max="180"/></el-form-item><el-form-item label="最大输出 Token"><el-input-number v-model="form.maxOutputTokens" :min="256" :max="16384"/></el-form-item><el-form-item label="每日请求上限"><el-input-number v-model="form.dailyRequestLimit" :min="1" :max="10000"/></el-form-item></div><el-form-item label="高级 输出长度参数"><el-select v-model="form.tokenParameter"><el-option label="max_tokens（多数兼容服务）" value="max_tokens"/><el-option label="max_completion_tokens" value="max_completion_tokens"/></el-select></el-form-item><p class="muted">额度和超时保护只影响新模型调用，不停止已经发布的数据解析、连接或转发规则。费用以提供商实际账单为准。</p></el-tab-pane>
</el-tabs></el-form><template #footer><el-button :disabled="busy" @click="drawer=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存服务</el-button></template></el-drawer>
</div></template>
<style scoped>.small-stat{font-size:19px!important}.el-form :deep(.el-select){width:100%}.el-form p{margin:10px 0 0}.stats-grid{grid-template-columns:repeat(4,minmax(0,1fr))}@media(max-width:1100px){.stats-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.stats-grid{grid-template-columns:1fr}}</style>
